def comps(g):
    h,w=len(g),len(g[0])
    seen=[[False]*w for _ in range(h)]; out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] not in (0,6) and not seen[r][c]:
                col=g[r][c]; q=deque([(r,c)]); seen[r][c]=True; comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==col:
