def transform(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(v for r in g for v in r)
    gcol=max((v for v in cnt if v!=0), key=lambda v: cnt[v])
    hdiv=[r for r in range(h) if all(g[r][c]==gcol for c in range(w))]
    vdiv=[c for c in range(w) if all(g[r][c]==gcol for r in range(h))]
    def band(r):
        b=0
        for i,d in enumerate(hdiv):
            if r>d: b=i+1
        return b
    groups={}
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v not in (0,gcol): groups.setdefault((v,band(r)),[]).append((r,c))
    out=[row[:] for row in g]
    for (col,b),pix in groups.items():
        cols=[c for _,c in pix]
        best=min(vdiv,key=lambda d:(min(abs(d-c) for c in cols), d))
        for r,c in pix:
            nc=2*best-c
            if not (0<=nc<w) or (g[r][nc] not in (0,col)): break
        else:
            for r,c in pix: out[r][2*best-c]=col
    return out

print('demo ok:', transform(I)==O)
